'use client'

import { useEffect, useRef, useState } from 'react'
import maplibregl from 'maplibre-gl'
import 'maplibre-gl/dist/maplibre-gl.css'
import { Protocol } from 'pmtiles'
import { usePMTilesStore } from '@/stores/pmtiles-store'
import { useResolutionStore } from '@/stores/resolution-store'
import { useTemporalStore } from '@/stores/temporal-store'
import { useUIStore } from '@/stores/ui-store'
import { getBasemapStyleForTheme } from '@/lib/basemaps'

interface HoverInfo {
  h3_id: string
  year: number
  h3_resolution: number
  pfas_grams: number
  pesticide_load: number
  applications: number
  field_count: number
  coverage: number
  area_ha: number
  pfas_intensity: number
  pesticide_intensity: number
}

interface BNBOHoverInfo {
  bnbo_id: string
  status_code: string
  status_description: string
  area_ha: number
}

type DataLayer = 'pfas' | 'total_pesticide' | 'diquat' | 'glyphosate'

interface PMTilesMapProps {
  className?: string
  pmtilesBaseUrl?: string
  initialYear?: number
  initialResolution?: number
  showBNBO?: boolean
  bnboOpacity?: number
  onBNBOToggle?: (visible: boolean) => void
  activeDataLayer?: DataLayer
}

export function PMTilesMap({ 
  className = '', 
  pmtilesBaseUrl = '/api/pmtiles',
  initialYear = 2023,
  initialResolution = 10,
  showBNBO = false,
  bnboOpacity = 0.4,
  onBNBOToggle,
  activeDataLayer = 'pfas'
}: PMTilesMapProps) {
  const mapContainer = useRef<HTMLDivElement>(null)
  const map = useRef<maplibregl.Map | null>(null)
  const [isLoaded, setIsLoaded] = useState(false)
  const [hoverInfo, setHoverInfo] = useState<HoverInfo | null>(null)
  const [bnboHoverInfo, setBNBOHoverInfo] = useState<BNBOHoverInfo | null>(null)
  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 })
  
  // Store hooks
  const { 
    setTileLoading, 
    setTileLoaded, 
    setTileError, 
    getTileKey,
    getTileStatus 
  } = usePMTilesStore()
  
  const { 
    currentResolution, 
    setResolution, 
    setZoom,
    getResolutionForZoom 
  } = useResolutionStore()
  
  const { currentYear, setCurrentYear } = useTemporalStore()
  const { theme } = useUIStore()
  
  // Determine if we should use dark mode
  const isDarkMode = theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches)
  
  // Initialize map with PMTiles protocol
  useEffect(() => {
    if (!mapContainer.current || map.current) return
    
    // Register PMTiles protocol
    const protocol = new Protocol()
    maplibregl.addProtocol('pmtiles', protocol.tile)
    
    // Create map with simple initial style
    map.current = new maplibregl.Map({
      container: mapContainer.current,
      style: {
        version: 8,
        sources: {},
        layers: [
          {
            id: 'background',
            type: 'background',
            paint: { 'background-color': isDarkMode ? '#0f172a' : '#f8f9fa' }
          }
        ]
      },
      center: [10.0, 56.0], // Denmark center
      zoom: 7,
      minZoom: 4,
      maxZoom: 15
    })
    
    // Add controls
    map.current.addControl(new maplibregl.NavigationControl(), 'top-right')
    map.current.addControl(new maplibregl.ScaleControl(), 'bottom-left')
    
    map.current.on('load', () => {
      setIsLoaded(true)
    })
    
    // Auto-resolution based on zoom
    map.current.on('zoom', () => {
      if (!map.current) return
      
      const zoom = map.current.getZoom()
      setZoom(zoom)
    })
    
    // Track mouse position for hover tooltip
    map.current.on('mousemove', (e) => {
      setMousePosition({ x: e.point.x, y: e.point.y })
    })
    
    // Cleanup
    return () => {
      if (map.current) {
        map.current.remove()
        map.current = null
      }
      maplibregl.removeProtocol('pmtiles')
    }
  }, [setZoom])

  // Update map style when theme changes
  useEffect(() => {
    if (!map.current || !isLoaded) return
    
    const getMapStyle = (dark: boolean) => ({
      version: 8,
      sources: {
        ...(dark ? {
          'protomaps-dark': {
            type: 'vector',
            url: 'pmtiles://https://build.protomaps.com/20241201.pmtiles'
          }
        } : {}),
        // Preserve existing sources
        ...Object.fromEntries(
          Object.entries(map.current!.getStyle().sources || {}).filter(([key]) => 
            key.includes('h3-') || key.includes('bnbo-')
          )
        )
      },
      layers: [
        // Base layers
        ...(dark ? [
          {
            id: 'background',
            type: 'background',
            paint: { 'background-color': '#0f172a' }
          },
          {
            id: 'water',
            type: 'fill',
            source: 'protomaps-dark',
            'source-layer': 'water',
            paint: {
              'fill-color': '#1e293b',
              'fill-opacity': 0.8
            }
          },
          {
            id: 'land',
            type: 'fill',
            source: 'protomaps-dark',
            'source-layer': 'land',
            paint: {
              'fill-color': '#0f172a'
            }
          },
          {
            id: 'roads',
            type: 'line',
            source: 'protomaps-dark',
            'source-layer': 'roads',
            paint: {
              'line-color': '#374151',
              'line-width': [
                'interpolate',
                ['linear'],
                ['zoom'],
                5, 0.5,
                10, 1,
                15, 2
              ]
            }
          },
          {
            id: 'places',
            type: 'symbol',
            source: 'protomaps-dark',
            'source-layer': 'places',
            layout: {
              'text-field': ['get', 'name'],
              'text-font': ['Open Sans Regular'],
              'text-size': [
                'interpolate',
                ['linear'],
                ['zoom'],
                5, 10,
                10, 12,
                15, 16
              ]
            },
            paint: {
              'text-color': '#9ca3af',
              'text-halo-color': '#0f172a',
              'text-halo-width': 1
            }
          }
        ] : [
          {
            id: 'background',
            type: 'background',
            paint: { 'background-color': '#f8f9fa' }
          }
        ]),
        // Preserve existing data layers
        ...Object.values(map.current!.getStyle().layers || []).filter((layer: any) => 
          layer.id.includes('h3-') || layer.id.includes('bnbo-')
        )
      ]
    })
    
    map.current.setStyle(getMapStyle(isDarkMode))
  }, [isDarkMode, isLoaded])
  
  // Update PMTiles layer when year, resolution, or data layer changes
  useEffect(() => {
    if (!map.current || !isLoaded) return
    
    updatePMTilesLayer(currentYear, currentResolution, activeDataLayer)
  }, [currentYear, currentResolution, activeDataLayer, isLoaded, pmtilesBaseUrl])
  
  // Update BNBO layer when visibility or opacity changes
  useEffect(() => {
    if (!map.current || !isLoaded) return
    
    updateBNBOLayer(showBNBO, bnboOpacity)
  }, [showBNBO, bnboOpacity, isLoaded, pmtilesBaseUrl])

  function getDataLayerColorExpression(dataLayer: DataLayer): any {
    switch (dataLayer) {
      case 'pfas':
        return [
          'case',
          ['>', ['get', 'pfas_grams'], 10], '#ef4444',    // red-500 - Very High
          ['>', ['get', 'pfas_grams'], 1], '#f59e0b',     // amber-500 - High  
          ['>', ['get', 'pfas_grams'], 0.1], '#3b82f6',   // blue-500 - Medium
          ['>', ['get', 'pfas_grams'], 0], '#10b981',     // emerald-500 - Low
          '#e2e8f0'                                       // slate-200 - No data
        ]
      case 'total_pesticide':
        return [
          'case',
          ['>', ['get', 'pesticide_load'], 100], '#ef4444',    // red-500 - Very High
          ['>', ['get', 'pesticide_load'], 10], '#f59e0b',     // amber-500 - High  
          ['>', ['get', 'pesticide_load'], 1], '#3b82f6',      // blue-500 - Medium
          ['>', ['get', 'pesticide_load'], 0], '#10b981',      // emerald-500 - Low
          '#e2e8f0'                                            // slate-200 - No data
        ]
      case 'diquat':
        return [
          'case',
          ['>', ['get', 'diquat_containing_active_ingredient_grams'], 10000], '#ef4444',    // red-500 - Very High (>10kg)
          ['>', ['get', 'diquat_containing_active_ingredient_grams'], 1000], '#f59e0b',     // amber-500 - High (1-10kg)
          ['>', ['get', 'diquat_containing_active_ingredient_grams'], 100], '#3b82f6',      // blue-500 - Medium (100g-1kg)
          ['>', ['get', 'diquat_containing_active_ingredient_grams'], 0], '#10b981',        // emerald-500 - Low (<100g)
          '#e2e8f0'                                                                         // slate-200 - No data
        ]
      case 'glyphosate':
        return [
          'case',
          ['>', ['get', 'glyphosate_containing_active_ingredient_grams'], 100000], '#ef4444',    // red-500 - Very High (>100kg)
          ['>', ['get', 'glyphosate_containing_active_ingredient_grams'], 10000], '#f59e0b',     // amber-500 - High (10-100kg)
          ['>', ['get', 'glyphosate_containing_active_ingredient_grams'], 1000], '#3b82f6',      // blue-500 - Medium (1-10kg)
          ['>', ['get', 'glyphosate_containing_active_ingredient_grams'], 0], '#10b981',         // emerald-500 - Low (<1kg)
          '#e2e8f0'                                                                              // slate-200 - No data
        ]
      default:
        return '#e2e8f0' // Default fallback
    }
  }

  function updatePMTilesLayer(year: number, resolution: number, dataLayer: DataLayer) {
    if (!map.current) return
    
    const layerId = 'h3-pfas'
    const sourceId = 'h3-pfas-source'
    const tileKey = getTileKey(year, resolution)
    
    // Remove existing layer and source
    if (map.current.getLayer(layerId)) {
      map.current.removeLayer(layerId)
    }
    if (map.current.getLayer(`${layerId}-outline`)) {
      map.current.removeLayer(`${layerId}-outline`)
    }
    if (map.current.getSource(sourceId)) {
      map.current.removeSource(sourceId)
    }
    
    // Add new PMTiles source
    const pmtilesUrl = `pmtiles://${pmtilesBaseUrl}/h3_pfas_${year}_res${resolution}.pmtiles`
    
    // Track loading state
    setTileLoading(tileKey, pmtilesUrl)
    
    try {
      map.current.addSource(sourceId, {
        type: 'vector',
        url: pmtilesUrl
      })
      
      // Add fill layer with resolution-aware styling
      map.current.addLayer({
        id: layerId,
        type: 'fill',
        source: sourceId,
        'source-layer': `h3_pfas_${year}_res${resolution}`,
        paint: {
          'fill-color': getDataLayerColorExpression(dataLayer),
          'fill-opacity': 0.8
        }
      })
      
      // Add outline with resolution-aware width
      map.current.addLayer({
        id: `${layerId}-outline`,
        type: 'line',
        source: sourceId,
        'source-layer': `h3_pfas_${year}_res${resolution}`,
        paint: {
          'line-color': '#64748b',  // slate-500 - subtle outline
          'line-width': resolution <= 8 ? 0.8 : 0.4,
          'line-opacity': 0.4
        }
      })
      
      // Enhanced hover functionality
      map.current.on('mouseenter', layerId, (e) => {
        if (map.current) {
          map.current.getCanvas().style.cursor = 'pointer'
        }
        
        if (e.features && e.features.length > 0) {
          const feature = e.features[0]
          const props = feature.properties
          
          if (props) {
            setHoverInfo({
              h3_id: props.h3_id || '',
              year: props.year || year,
              h3_resolution: props.h3_resolution || resolution,
              pfas_grams: props.pfas_grams || 0,
              pesticide_load: props.pesticide_load || 0,
              applications: props.applications || 0,
              field_count: props.field_count || 0,
              coverage: props.coverage || 0,
              area_ha: props.area_ha || 0,
              pfas_intensity: props.pfas_intensity || 0,
              pesticide_intensity: props.pesticide_intensity || 0,
            })
          }
        }
      })
      
      map.current.on('mouseleave', layerId, () => {
        if (map.current) {
          map.current.getCanvas().style.cursor = ''
        }
        setHoverInfo(null)
      })
      
      // Click handler for detailed popup
      map.current.on('click', layerId, (e) => {
        if (!e.features || e.features.length === 0) return
        
        const feature = e.features[0]
        const properties = feature.properties
        
        if (!properties) return
        
        // Create detailed popup
        const popup = new maplibregl.Popup({
          closeButton: true,
          closeOnClick: true,
          maxWidth: '400px'
        })
        
        // Get PFAS level for color coding
        const pfasGrams = properties.pfas_grams || 0
        const pfasLevel = pfasGrams > 10 ? 'Very High' : pfasGrams > 1 ? 'High' : pfasGrams > 0.1 ? 'Medium' : 'Low'
        const pfasColor = pfasGrams > 10 ? '#ef4444' : pfasGrams > 1 ? '#f59e0b' : pfasGrams > 0.1 ? '#3b82f6' : '#10b981'
        
        const popupContent = `
          <div class="p-4 max-w-sm">
            <div class="flex items-center justify-between mb-3">
              <div>
                <h3 class="font-semibold text-slate-900">H3 Cell</h3>
                <p class="text-xs text-slate-500">Resolution ${properties.h3_resolution || resolution} • ${properties.year || year}</p>
              </div>
              <div class="flex items-center space-x-2">
                <div class="w-3 h-3 rounded-full" style="background-color: ${pfasColor}"></div>
                <span class="text-xs font-medium text-slate-700">${pfasLevel}</span>
              </div>
            </div>
            
            <div class="space-y-3">
              <div>
                <div class="text-lg font-bold text-slate-900">${pfasGrams.toFixed(2)} g</div>
                <div class="text-xs text-slate-600">Total PFAS</div>
              </div>
              
              <div class="grid grid-cols-2 gap-3 text-sm">
                <div>
                  <div class="font-medium text-slate-900">${(properties.pesticide_load || 0).toFixed(1)} kg</div>
                  <div class="text-xs text-slate-600">Pesticides</div>
                </div>
                <div>
                  <div class="font-medium text-slate-900">${properties.field_count || 0}</div>
                  <div class="text-xs text-slate-600">Fields</div>
                </div>
                <div>
                  <div class="font-medium text-slate-900">${(properties.area_ha || 0).toFixed(1)} ha</div>
                  <div class="text-xs text-slate-600">Area</div>
                </div>
                <div>
                  <div class="font-medium text-slate-900">${((properties.coverage || 0) * 100).toFixed(0)}%</div>
                  <div class="text-xs text-slate-600">Coverage</div>
                </div>
              </div>
            </div>
          </div>
        `
        
        popup
          .setLngLat(e.lngLat)
          .setHTML(popupContent)
          .addTo(map.current!)
      })
      
      setTileLoaded(tileKey)
    } catch (error) {
      console.error('Failed to load PMTiles:', error)
      setTileError(tileKey, error instanceof Error ? error.message : 'Unknown error')
    }
  }
  
  function updateBNBOLayer(visible: boolean, opacity: number) {
    if (!map.current) return
    
    const layerId = 'bnbo-areas'
    const sourceId = 'bnbo-areas-source'
    
    // Remove existing layer and source
    if (map.current.getLayer(layerId)) {
      map.current.removeLayer(layerId)
    }
    if (map.current.getLayer(`${layerId}-outline`)) {
      map.current.removeLayer(`${layerId}-outline`)
    }
    if (map.current.getSource(sourceId)) {
      map.current.removeSource(sourceId)
    }
    
    if (!visible) return
    
    // Add BNBO PMTiles source - use direct GCS URL
    const pmtilesUrl = `pmtiles://https://storage.googleapis.com/landbrugsdata-raw-data/pmtiles/bnbo_areas.pmtiles`
    
    try {
      map.current.addSource(sourceId, {
        type: 'vector',
        url: pmtilesUrl
      })
      
      // Add fill layer with status-based styling
      map.current.addLayer({
        id: layerId,
        type: 'fill',
        source: sourceId,
        'source-layer': 'bnbo_areas',
        paint: {
          'fill-color': [
            'case',
            ['==', ['get', 'status_code'], 'action_required'], '#ff6b6b',
            ['==', ['get', 'status_code'], 'completed'], '#51cf66',
            '#868e96' // unknown
          ],
          'fill-opacity': opacity
        }
      })
      
      // Add outline
      map.current.addLayer({
        id: `${layerId}-outline`,
        type: 'line',
        source: sourceId,
        'source-layer': 'bnbo_areas',
        paint: {
          'line-color': [
            'case',
            ['==', ['get', 'status_code'], 'action_required'], '#e03131',
            ['==', ['get', 'status_code'], 'completed'], '#37b24d',
            '#495057' // unknown
          ],
          'line-width': 1.5,
          'line-opacity': 0.8
        }
      })
      
      // BNBO hover functionality
      map.current.on('mouseenter', layerId, (e) => {
        if (map.current) {
          map.current.getCanvas().style.cursor = 'pointer'
        }
        
        if (e.features && e.features.length > 0) {
          const feature = e.features[0]
          const props = feature.properties
          
          if (props) {
            setBNBOHoverInfo({
              bnbo_id: props.bnbo_id || '',
              status_code: props.status_code || 'unknown',
              status_description: props.status_description || 'Unknown',
              area_ha: props.area_ha || 0,
            })
          }
        }
      })
      
      map.current.on('mouseleave', layerId, () => {
        if (map.current) {
          map.current.getCanvas().style.cursor = ''
        }
        setBNBOHoverInfo(null)
      })
      
      // BNBO click handler
      map.current.on('click', layerId, (e) => {
        if (!e.features || e.features.length === 0) return
        
        const feature = e.features[0]
        const properties = feature.properties
        
        if (!properties) return
        
        // Create detailed popup
        const popup = new maplibregl.Popup({
          closeButton: true,
          closeOnClick: true,
          maxWidth: '350px'
        })
        
        const statusColor = 
          properties.status_code === 'action_required' ? '#ff6b6b' :
          properties.status_code === 'completed' ? '#51cf66' : '#868e96'
        
        const popupContent = `
          <div class="p-4">
            <div class="border-b pb-2 mb-3">
              <h3 class="font-bold text-lg text-gray-900">BNBO Area</h3>
              <p class="text-sm text-gray-600">Protected Environmental Area</p>
            </div>
            
            <div class="space-y-3 text-sm">
              <div>
                <span class="font-medium text-gray-700">BNBO ID:</span>
                <p class="text-gray-900 font-mono">${properties.bnbo_id || 'N/A'}</p>
              </div>
              <div>
                <span class="font-medium text-gray-700">Area:</span>
                <p class="text-gray-900">${(properties.area_ha || 0).toFixed(2)} ha</p>
              </div>
              <div>
                <span class="font-medium text-gray-700">Status:</span>
                <div class="flex items-center space-x-2 mt-1">
                  <div class="w-3 h-3 rounded-full" style="background-color: ${statusColor}"></div>
                  <span class="text-gray-900">${properties.status_description || 'Unknown'}</span>
                </div>
              </div>
            </div>
          </div>
        `
        
        popup
          .setLngLat(e.lngLat)
          .setHTML(popupContent)
          .addTo(map.current!)
      })
      
    } catch (error) {
      console.error('Failed to load BNBO PMTiles:', error)
    }
  }
  
  return (
    <div className={`relative ${className}`}>
      <div ref={mapContainer} className="w-full h-full" />
      
      {/* PMTiles status indicator */}
      {isLoaded && (
        <div className="absolute top-4 right-4 bg-white rounded-lg shadow-lg p-2 text-xs">
          <div className="text-green-600">
            ✅ PMTiles: {currentYear} (res {currentResolution})
          </div>
          <div className="text-gray-500">
            Status: {getTileStatus(currentYear, currentResolution)}
          </div>
          {showBNBO && (
            <div className="text-blue-600">
              🛡️ BNBO Areas: Active
            </div>
          )}
        </div>
      )}
      
      {/* Modern Hover tooltip */}
      {(hoverInfo || bnboHoverInfo) && (
        <div 
          className="absolute bg-white border border-slate-200 rounded-lg shadow-lg p-3 pointer-events-none z-10 max-w-xs"
          style={{
            left: mousePosition.x + 10,
            top: mousePosition.y - 10,
            transform: mousePosition.x > window.innerWidth - 300 ? 'translateX(-100%)' : 'none'
          }}
        >
          {hoverInfo && (
            <>
              <div className="text-sm font-medium text-slate-900 mb-2">
                H3 Cell • Resolution {hoverInfo.h3_resolution}
              </div>
              <div className="space-y-1.5">
                <div className="flex justify-between text-sm">
                  <span className="text-slate-600">PFAS:</span>
                  <span className="font-medium text-slate-900">{hoverInfo.pfas_grams.toFixed(2)} g</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-slate-600">Pesticides:</span>
                  <span className="font-medium text-slate-900">{hoverInfo.pesticide_load.toFixed(1)} kg</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-slate-600">Area:</span>
                  <span className="font-medium text-slate-900">{hoverInfo.area_ha.toFixed(1)} ha</span>
                </div>
              </div>
            </>
          )}
          
          {bnboHoverInfo && (
            <>
              <div className="text-sm font-medium text-slate-900 mb-2">
                BNBO Protected Area
              </div>
              <div className="space-y-1.5">
                <div className="flex justify-between text-sm">
                  <span className="text-slate-600">Status:</span>
                  <span className="font-medium text-slate-900">{bnboHoverInfo.status_description}</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-slate-600">Area:</span>
                  <span className="font-medium text-slate-900">{bnboHoverInfo.area_ha.toFixed(1)} ha</span>
                </div>
              </div>
            </>
          )}
        </div>
      )}
      
      {/* Color legend */}
      <div className="absolute bottom-4 left-4 z-10">
        <div className="bg-white rounded-lg shadow-lg p-4">
          <h3 className="font-bold text-sm mb-2">PFAS Concentration</h3>
          <div className="space-y-1 text-xs">
            <div className="flex items-center">
              <div className="w-4 h-4 bg-[#d73027] mr-2"></div>
              <span>&gt; 100g</span>
            </div>
            <div className="flex items-center">
              <div className="w-4 h-4 bg-[#f46d43] mr-2"></div>
              <span>50-100g</span>
            </div>
            <div className="flex items-center">
              <div className="w-4 h-4 bg-[#fdae61] mr-2"></div>
              <span>10-50g</span>
            </div>
            <div className="flex items-center">
              <div className="w-4 h-4 bg-[#fee08b] mr-2"></div>
              <span>1-10g</span>
            </div>
            <div className="flex items-center">
              <div className="w-4 h-4 bg-[#e6f598] mr-2"></div>
              <span>0-1g</span>
            </div>
            <div className="flex items-center">
              <div className="w-4 h-4 bg-[#abdda4] mr-2"></div>
              <span>No data</span>
            </div>
          </div>
          
          {showBNBO && (
            <>
              <div className="mt-3 pt-3 border-t">
                <h4 className="font-bold text-sm mb-2">BNBO Areas</h4>
                <div className="space-y-1 text-xs">
                  <div className="flex items-center">
                    <div className="w-4 h-4 bg-[#ff6b6b] mr-2"></div>
                    <span>Action Required</span>
                  </div>
                  <div className="flex items-center">
                    <div className="w-4 h-4 bg-[#51cf66] mr-2"></div>
                    <span>Completed</span>
                  </div>
                  <div className="flex items-center">
                    <div className="w-4 h-4 bg-[#868e96] mr-2"></div>
                    <span>Unknown</span>
                  </div>
                </div>
              </div>
            </>
          )}
          
          <div className="mt-3 pt-3 border-t text-xs text-gray-600">
            <p className="mb-1">Current resolution: {currentResolution}</p>
            <div className="space-y-1">
              <div>7-8: Regional view</div>
              <div>9: Municipal view</div>
              <div>10: Field level detail</div>
            </div>
          </div>
        </div>
      </div>
      
      {/* Loading indicator */}
      {!isLoaded && (
        <div className="absolute inset-0 bg-gray-100 flex items-center justify-center">
          <div className="text-center">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 mx-auto mb-2"></div>
            <p className="text-sm text-gray-600">Loading map...</p>
          </div>
        </div>
      )}
    </div>
  )
}